6,-0.02761636,-0.007689918,-0.0042673456,0.01749321,0.0239452,0.002307352,0.11246534,0.0074847774,0.008708322,0.0037957956,0.010402312,-0.021465026,0.011969095,-0.029192315,0.0069768145,-0.02490096,0.028064312,-0.022535963,-0.03885345,-0.019486208,0.0026373323,0.02063623,-0.061305843,-0.029064035,0.012631855,0.00012335351,-0.03188425,0.024972863,-0.020838961,0.058279168,-0.04211961,-0.050132915,0.0052812104,-0.01891527,-0.0259234,-0.011932901,-0.020615255,-0.043221757,0.0116385,0.037603375,0.044310406,0.00032347604]'::vector, now(), now());
