VALUES ('017e4696-fe42-4cc9-a995-fd2e7bc75165', '00000000-0000-4000-8000-000000000400', 'By the 1870s, Menilek incorporated the Tulama and eastern Macha Oromo territories. The Shewan Oromo notables like Ras Gobana Dache played a pivotal role in the territorial expansion and the creation of the modern Ethiopian Empire. In this decade, the northern Gurage, the Kistane or Soddo Gurage peacefully submitted without resistance to Menilek while the western Gurage, led by Hassan Enjamo of Qabena, strongly resisted Menilek’s force until Ras Gobana defeated them in 1888.', 'G10-History-STB-2023-web.pdf p.1', '2026.1', 'published', '[0.034185547,0.023866951,-0.012493124,0.0070039886,0.0076823556,-0.016381837,-0.019767463,-0.05424631,0.011533262,-0.10676083,-0.0022017218,-0.015579762,0.03484128,0.051535428,-0.06530984,-0.035540067,0.01427691,-0.043157812,0.0096958075,-0.01841665,0.07297877,-0.010404349,0.04119055,0.06731859,-0.032807313,0.013523144,-0.019039296,-0.056962457,-0.00575185,0.19052444,-0.02219669,-0.019276097,0.015815502,-0.018191643,0.013738293,0.0017577196,-0.011305498,0.03495451,-0.009525348,-0.03463652,0.003943975,-0.014599771,0.0032141707,0.020282188,0.072037496,-0.009209999,0.025417604,0.03246108,-0.00938036,-0.026229978,0.010997563,-0.0056098034,-0.0072544073,-0.061965186,0.046127107,0.011096999,0.005237215,0.01259638,0.022787288,0.016355334,-0.008434293,0.011248873,0.013710233,0.012343819,-0.02932928,0.027380412,0.014709409,0.025298752,0.05753778,0.0391761,0.040391732,0.012521519,0.004699281,0.01865308,-0.028975317,0.015376459,-0.025460923,0.011656137,0.05260431,0.021137046,0.05755281,0.023562338,0.0024374747,-0.0071106637,-0.010285872,-0.02015627,-0.01928565,-0.010833914,0.0141314985,0.0076475935,0.030020585,-0.01850525,-0.011475522,-0.06170647,0.05956849,0.0072379527,-0.01965355,-0.007678613,0.016797256,0.02542508,0.016342448,0.026922088,0.030922724,0.017935285,-0.004337552,-0.00022141957,0.00062333106,0.029896408,0.0008989016,0.03462958,-0.026970904,-0.30